        // @call roundUnit
        'month' => [1, static::MONTHS_PER_YEAR],
        // @call roundUnit
        'day' => [1, $daysInMonth],
        // @call roundUnit
        'hour' => [0, static::HOURS_PER_DAY - 1],
        // @call roundUnit
        'minute' => [0, static::MINUTES_PER_HOUR - 1],
        // @call roundUnit
        'second' => [0, static::SECONDS_PER_MINUTE - 1],
    ];
}

